"""Answer the v17 stress review from saved evidence, preserving all old tables."""
from pathlib import Path
import json,re
from docx import Document
from docx.shared import Cm,Pt
from build_v17 import write
from build_corrected_manuscript import paragraph,table
ROOT=Path(__file__).resolve().parent.parent;OLD=ROOT/'revision_17_final_2026-11-01';OUT=ROOT/'revision_18_2026-11-01'
LABEL={'iid':'IID','correlated_iid_fit':'AR / IID','correlated_gls_fit':'AR / GLS','correlated_fgls_fit':'AR / FGLS','gain5_iid_fit':'Gain +5%','operator_iid_fit':'Operator','rotation_harmonics':'Rotation 1× + 2×','tooth_harmonic':'Tooth pass'}
def f(a):return '—' if a is None else f'{a:.3g}'
def main():
    a=json.loads((OUT/'analysis_v18.json').read_text());cells=a['cells'];boot=a['bootstrap'];assert a['selected_cases']==1100
    def cell(sd,c):return next(x for x in cells if x['sd']==sd and x['scenario']==c)
    gain=next(x for x in boot if x['sd']==.4 and x['A']=='gain5_iid_fit' and x['n']==200)['metrics']['dedendum_error']
    d=Document(OLD/'MMT_manuscript_Q1_revision_v17_clean.docx');changes=[]
    def patch(prefix,text):
        p=next(p for p in d.paragraphs if p.text.startswith(prefix));changes.append(dict(before=p.text,after=text));write(p,text);return p
    oldabs=next(p.text for p in d.paragraphs if p.text.startswith('Inferring gear microgeometry'))
    abst=oldabs.replace('A further 500 synthetic stress cases assess correlated noise, gain and operator mismatch.','With 200 paired realizations, a 5% gain raises deeper-case median scaled error from '+f(gain['median_B'])+' to '+f(gain['median_A'])+'; the 95% paired-bootstrap median-difference interval is '+f(gain['lower'])+'–'+f(gain['upper'])+'.')
    assert len(abst.split())<=250;patch('Inferring gear microgeometry',abst)
    # Replace the old stress subsection as a unit; all preceding results remain.
    first=next(p for p in d.paragraphs if p.text.startswith('4.8 '));anchor=next(p for p in d.paragraphs if p.text=='5 Discussion');node=first._p
    while node is not anchor._p:
        nxt=node.getnext();node.getparent().remove(node);node=nxt
    def insert(text,style=None):
        p=paragraph(d,'',style);write(p,text);anchor._p.addprevious(p._p);return p
    insert('4.8 Noise measurement errors and operator stress','Heading 2')
    insert('The stress study uses G0, 300 Nm, 120 canonical phases, σ=0.1 µm and θ=(0.020,0.75,0.005,s_d), with s_d=0.25 and 0.40. Projected-energy compliance is used for inversion. The original five scenarios have 50 paired realizations per truth: IID Gaussian noise; stationary nonperiodic AR noise with C_ij=0.8^|i−j| fitted as IID; the same observations fitted by known-covariance GLS; an unmodelled 5% gain plus IID noise; and shear-G generation with projected-energy inversion plus IID noise. The deeper IID and gain scenarios are extended to 200 paired seeds. Three additional scenarios have 50 realizations per truth: rotation harmonics, a tooth-pass harmonic and one-step feasible GLS (FGLS) fitted to the same AR observations. The 1100 selected fits comprise the original 500 and 600 additional cases; the unequal cell sizes are stated explicitly.')
    insert('Rotation-error controls add 0.1 µm-amplitude cosines at 1× and 2× pinion rotation with independent uniform phases; their angular frequencies over one tooth-pass record are 2π/24 and 4π/24. The tooth-pass control adds a cosine of 0.1 µm RMS over that record. Both add the same σ=0.1 µm IID noise as the baseline. Harmonics are centred on the sampled window; rotation harmonics therefore retain their prescribed full-rotation amplitudes and generally have much less than 0.1 µm RMS over a single tooth pass. Motivated by transmission-error measurement and angular-sampling issues [35], these controlled periodic errors represent possible encoder or mounting contamination without claiming a calibrated model of either mechanism. Their realized window RMS and random phases are reproducible from the archived seeds. They complement the generic AR stress, rather than establish its physical covariance.')
    insert('FGLS first fits the AR observations with the three IID-weighted starts. From the selected pilot residual, after subtracting its sample mean, it estimates ρ by the lag-one product divided by the lag-zero product of the first 119 residuals, clipped to [−0.95,0.95]. The marginal standard deviation is the residual RMS, floored at 10⁻⁸ mm. A fixed AR covariance with these estimates is used for one GLS refit from the original three starts. This is a structured plug-in covariance estimate from 120 residuals; it is not a calibrated estimate of physical discrepancy. Its data-dependent weighted score cannot be assigned the known-covariance chi-square reference. FGLS additionally requires the pilot optimization, so this comparison does not claim equal-budget computational efficiency.')
    insert('All final fits use bounded scaled trust-region least squares with the analytic tangent, at most 600 function evaluations and ftol=10⁻⁹, xtol=10⁻¹⁰, gtol=10⁻⁸. The three starts are (0.030,0.65,0.010,0.35), (0.015,0.85,0.020,0.45) and (0.010,0.50,0.040,0.48), with depths in mm. The smallest final objective is retained even if flagged nonconverged. A bound hit lies within 10⁻⁶ of an interval width from a bound. Seeds 2026110100+i generate innovations and 2026111800+i generate harmonic phases; i=0–49 except for the deeper IID/gain controls, where i=0–199. Noise is added after centring the deterministic curve and is not recentered. There are '+str(a['final_attempts'])+' final attempts and '+str(a['pilot_attempts'])+' additional covariance-pilot attempts, with '+str(a['failed_selected'])+' selected fits, '+str(a['failed_final_attempts'])+' final attempts and '+str(a['failed_pilot_attempts'])+' pilot attempts flagged nonconverged. All are retained; no global-minimum certificate is asserted.')
    gl=cell(.25,'correlated_gls_fit');ii=cell(.25,'correlated_iid_fit');bg=next(x for x in boot if x['sd']==.25 and x['A']=='correlated_gls_fit');bc=bg['joint_converged_interior'];loc=a['local_linear_covariance'][0]
    insert('The marginal GLS result is not explained solely by box saturation. Known-covariance GLS gives '+str(gl['any_bound'])+'/50 dedendum bound hits versus '+str(ii['any_bound'])+'/50 under IID weighting; the separate depth/start counts are '+str(gl['depth_bound'])+'/'+str(gl['start_bound'])+' versus '+str(ii['depth_bound'])+'/'+str(ii['start_bound'])+' (overlap is possible). Among '+str(bc['n'])+' paired realizations where both fits converge with interior dedendum estimates, median scaled errors remain '+f(bc['median_A'])+' versus '+f(bc['median_B'])+'. The unbounded local linear model predicts lower scaled depth standard deviation for GLS ('+f(loc['scaled_linear_std_gls'][2])+' versus '+f(loc['scaled_linear_std_ols'][2])+'), but both exceed the entire admissible scaled depth width of 5 (Table S32). Linear covariance efficiency therefore does not predict the median of this bounded nonlinear error statistic. These diagnostics do not establish that transition-phase weighting causes the observed ordering.')
    deep_gls=next(b for b in boot if b['sd']==.4 and b['A']=='correlated_gls_fit')['metrics']['dedendum_error']
    insert('At deeper support, the paired GLS-minus-IID-weighting difference of medians on the same AR observations is '+f(deep_gls['difference'])+', with 95% percentile interval ['+f(deep_gls['lower'])+', '+f(deep_gls['upper'])+']. This sample does not resolve an ordering of that error statistic between the two weights.')
    insert('Paired percentile bootstraps resample seed indices jointly, using 10000 replicates and seed 20261118. The statistic is median(error_A)−median(error_B), distinct from the median of paired errors used in Tables 6–7. For the deeper 200-seed gain comparison, the medians are '+f(gain['median_A'])+' and '+f(gain['median_B'])+'; their difference is '+f(gain['difference'])+' with 95% percentile interval ['+f(gain['lower'])+', '+f(gain['upper'])+']. Table S30 also retains the original 50-pair comparison, GLS/FGLS contrasts and profile/transfer-error intervals. These pointwise intervals are not adjusted for multiple contrasts and quantify finite simulation-sample uncertainty under the declared operators and fitting procedure; they do not establish physical parameter coverage or precise tail probabilities.')
    insert('For every fit, Table S28 reports complete-profile RMSE on 1001 flank points and noise-free transfer errors at 200 Nm on 240 phases, which are not used for fitting. Transfer is assessed against both the nominal projected-energy truth and the scenario-specific generating response, retaining the gain, shear formulation or harmonic where applicable. These targets distinguish profile error, compensation and prediction within the declared reduced operators; neither target is independent physical validation. Table S29 reports observation residual RMS and Q/120, where Q is the sum of squared residuals after whitening by the assumed covariance. For FGLS, whitening uses the estimated covariance, and its score is descriptive.')
    insert('Different error measures need not rank the methods alike. For the marginal AR observations, known-covariance GLS increases median profile RMSE from '+f(ii['profile_um'])+' to '+f(gl['profile_um'])+' µm but reduces nominal-target transfer RMSE from '+f(ii['heldout_nominal_um'])+' to '+f(gl['heldout_nominal_um'])+' µm. Thus the larger dedendum error is not evidence of uniformly poorer prediction. For FGLS, median estimated ρ values are '+f(cell(.25,'correlated_fgls_fit')['rho_estimated'])+' and '+f(cell(.4,'correlated_fgls_fit')['rho_estimated'])+', and median marginal noise estimates are '+f(cell(.25,'correlated_fgls_fit')['sigma_estimated_um'])+' and '+f(cell(.4,'correlated_fgls_fit')['sigma_estimated_um'])+' µm for the two truths, below the generating 0.8 and 0.1 µm. A training Q/120 near one with this plug-in covariance does not validate the covariance estimate.')
    ci=cell(.4,'iid');cg=cell(.4,'gain5_iid_fit')
    screen=('Thus the gain distortion is flagged in every computed fit in this control, including '+str(cg['failed'])+' nonconverged selections. This outcome is conditional on the declared operator, noise and finite search.' if cg['score_flags']==cg['n'] else 'Among gain fits passing the screen, median scaled dedendum error is '+f(cg['screen_pass_error_median'])+'.')
    insert('As a screening diagnostic, Table S29 counts Q>'+format(a['score_cutoff'],'.3f')+', the 95th percentile of χ² with 120 degrees of freedom. This compares against the known-truth noise budget without subtracting a fitted parameter count. Under a correct fixed covariance and exact minimization, fitting cannot increase the objective above its value at the admissible truth, making this a conservative screen; finite optimization can also trigger a flag. With incorrectly assumed covariance its nominal false-alarm interpretation does not apply, and no flag rate is assigned to FGLS. In the deeper 200-pair controls, '+str(cg['score_flags'])+'/200 gain fits and '+str(ci['score_flags'])+'/200 IID fits cross the screen. '+screen+' A flag tests compatibility of operator, error model and optimization together, and does not identify the cause; passing it is not an identifiability certificate. The twelve external amplitudes cannot calibrate this waveform score or covariance.')
    pic=d.add_paragraph();pic.paragraph_format.keep_with_next=True;pic.add_run().add_picture(str(OUT/'stress_v18.png'),width=Cm(16));anchor._p.addprevious(pic._p)
    cap=insert('Figure 12 Stress errors on a logarithmic scale, separated by generating truth. Each cell has 50 paired seeds except the deeper IID and gain controls, which have 200. Blue circles denote converged interior dedendum estimates, red crosses converged bound hits and black plus signs nonconverged selections. Black bars show medians over all selections. GLS uses known AR covariance; FGLS estimates a fixed AR covariance from pilot residuals. Rotation harmonics retain 0.1 µm full-rotation amplitudes; the tooth-pass harmonic has 0.1 µm RMS on the observation window.');cap.paragraph_format.keep_together=True
    for r in cap.runs:r.font.size=Pt(9)
    p=next(p for p in d.paragraphs if p.text.startswith('The finite stress controls extend'))
    patch('The finite stress controls extend','The stress controls extend the numerical evidence to correlated noise, known and estimated covariance, periodic measurement errors, gain and a change of compliance formulation. With 200 paired deeper-case realizations, a 5% gain raises median scaled dedendum error from '+f(gain['median_B'])+' to '+f(gain['median_A'])+'; the 95% paired-bootstrap interval for the difference of medians is ['+f(gain['lower'])+', '+f(gain['upper'])+']. Residual screening and noise-free transfer quantify consequences within the assumed operators, without establishing physical profile recovery. The defensible outcome remains an operator-conditioned account of observability and uncertainty, together with a pre-inversion support check. Independent mechanical and experimental validation remains necessary for physical reconstruction.')
    p=next(p for p in d.paragraphs if p.text.startswith('Limitations and outlook.'))
    patch('Limitations and outlook.',p.text.replace('The finite stress controls in Section 4.8 relax the independent-noise and same-compliance assumptions under specified synthetic alternatives.','The stress controls in Section 4.8 relax the independent-noise and same-compliance assumptions and add periodic errors and estimated covariance under specified synthetic alternatives.').replace('these follow-ups have not been performed here.','the new periodic-error and covariance controls address part of the final row, while the physical follow-ups remain unperformed. A single deterministic FE waveform difference would characterize phase-dependent discrepancy, but would not by itself estimate a stochastic discrepancy covariance without replication or additional modelling assumptions.'))
    patch('Data availability.','Data availability. Current code, raw observations, all 1100 selected stress cases, 3300 final fitting attempts and 300 covariance-pilot attempts, bootstrap replicates, transfer diagnostics, source hashes and construction files are supplied in MMT_reproducibility_v18.zip. Earlier numerical campaigns are preserved unchanged. The preceding version-13 baseline is public at https://github.com/romusan/gears-inversion-reproducibility/tree/manuscript-v13; it does not include subsequent controls or this revision. No repository DOI is currently assigned.')
    # Precise covariance count is audited against saved records below.
    assert a['final_attempts']==3300 and a['pilot_attempts']==300
    d.core_properties.version='18';d.save(OUT/'MMT_manuscript_Q1_revision_v18_clean.docx')
    s=Document(OLD/'MMT_supplementary_Q1_revision_v17.docx')
    paragraph(s,'Additional stress diagnostics and extended gain control','Heading 1')
    def caption(text):
        p=paragraph(s,text);p.paragraph_format.keep_with_next=True;p.paragraph_format.keep_together=True
    caption('Supplementary Table S28 Extended stress and noise-free transfer. S24–S25 retain the original 50-seed results; this table supersedes their deeper IID/gain summaries with 200 paired seeds and adds three scenarios. D is median scaled dedendum error; P is complete-profile RMSE; H₀ and H_g are transfer RMSE at 200 Nm and 240 phases against nominal and generating targets, respectively (all RMSE in µm). F counts failed selected fits. All medians include failed selections.')
    table(s,['s_d','Scenario','n','D','P','H₀','H_g','F'],[[str(c['sd']),LABEL[c['scenario']],str(c['n'])]+[f(c[k]) for k in ['dedendum_error','profile_um','heldout_nominal_um','heldout_generator_um']]+[str(c['failed'])] for c in cells],[.8,3,1,1.6,1.8,1.8,1.8,1])
    caption('Supplementary Table S29 Residual compatibility diagnostics. δ is median deterministic window bias RMS (µm), R is median observation residual RMS (µm); Q/n is the median assumed-covariance weighted squared residual divided by 120. Flag counts use Q>'+format(a['score_cutoff'],'.3f')+' (χ²₁₂₀ 95th percentile). This is a conservative known-truth screen only under correct fixed covariance and exact minimization; other flag rates are operational comparisons, not calibrated detection probabilities. FGLS estimates covariance from the same observations, so no chi-square flag rate is assigned.')
    table(s,['s_d','Scenario','n','δ µm','R µm','Q/n','Flags'],[[str(c['sd']),LABEL[c['scenario']],str(c['n']),f(c['window_bias_um']),f(c['residual_um']),f(c['Q_per_n']),str(c['score_flags']) if c['score_flags'] is not None else '—'] for c in cells],[.9,3.5,1,2.1,2.1,2.1,1.8])
    caption('Supplementary Table S30 Paired differences of medians A−B with 10000 paired percentile-bootstrap replicates, seed 20261118. Gain contrasts use IID baseline; GLS and FGLS contrasts use AR observations fitted as IID. D is scaled dedendum error, P profile RMSE and H₀ nominal-target transfer RMSE (µm). Pointwise intervals are not adjusted for multiple contrasts and concern simulation-sample uncertainty, not physical parameter confidence coverage. n=50 and n=200 gain comparisons are nested, not independent replications.')
    br=[]
    for b in boot:
        for key,label in [('dedendum_error','D'),('profile_um','P'),('heldout_nominal_um','H₀')]:
            m=b['metrics'][key];br.append([str(b['sd']),LABEL[b['A']]+' − '+LABEL[b['B']],str(b['n']),label,f(m['difference']),f(m['lower']),f(m['upper'])])
    table(s,['s_d','A − B','n','Metric','Δ median','2.5%','97.5%'],br,[1,4,1,1.5,2,2,2])
    caption('Supplementary Table S31 Anatomy of the AR fits, 50 paired realizations per truth and weighting. Counts include all selected fits, including failures; bounds use 10⁻⁶ of interval width. C and s denote dedendum depth and start. L/U denote lower/upper bounds. Counts can overlap. D_I is median scaled error among converged interior dedendum estimates; paired joint-interior sensitivity is reported in analysis_v18.json and Section 4.8.')
    records=[json.loads(x) for x in (OUT/'derived_records.jsonl').read_text().splitlines()];raw=[json.loads(x) for p in [OLD/'stress_records.jsonl',OUT/'extension_records.jsonl'] for x in p.read_text().splitlines()];lookup={(r['sd_true'],r['scenario'],r['seed']):r for r in raw};br=[]
    for c in cells:
        if not c['scenario'].startswith('correlated_'):continue
        rr=[lookup[(r['sd_true'],r['scenario'],r['seed'])] for r in records if r['sd_true']==c['sd'] and r['scenario']==c['scenario']]
        counts=[sum(r['bound_flags'][j] and (r['theta'][j]<mid if side=='L' else r['theta'][j]>=mid) for r in rr) for j,mid,side in [(2,.025,'L'),(2,.025,'U'),(3,.275,'L'),(3,.275,'U')]]
        br.append([str(c['sd']),LABEL[c['scenario']],str(c['any_bound'])]+list(map(str,counts))+[f(c['interior_median'])])
    table(s,['s_d','Weighting','Any','C L','C U','s L','s U','D_I'],br,[1,3,1.6,1.4,1.4,1.4,1.4,2])
    caption('Supplementary Table S32 Unbounded local linear propagation of the known AR(0.8) covariance at the generating truths. Standard deviations are in scaled parameter coordinates; depth is scaled by 0.01 mm and start by 1. Bounds are excluded from this calculation. The full admissible scaled widths are 5 for depth and 0.45 for start. A local variance ordering does not imply an ordering of bounded nonlinear median errors.')
    br=[]
    for l in a['local_linear_covariance']:
        for weight,key in [('IID','scaled_linear_std_ols'),('GLS','scaled_linear_std_gls')]:br.append([str(l['sd']),weight,f(l[key][2]),f(l[key][3]),'5','0.45'])
    table(s,['s_d','Weighting','SD depth','SD start','Depth width','Start width'],br,[1,2,2.6,2.6,3,3])
    for t in s.tables[27:]:
        t.columns[0].width=Cm(1.2)
        for row in t.rows:row.cells[0].width=Cm(1.2)
        if t.cell(0,0).text=='s_d':
            p=t.cell(0,0).paragraphs[0];p.clear()
            for value,sub in [('s',False),('d',True)]:
                r=p.add_run(value);r.font.subscript=sub;r.font.size=Pt(9);r.bold=True
    s.core_properties.version='18';s.save(OUT/'MMT_supplementary_Q1_revision_v18.docx')
    h=Document(OLD/'Highlights_v17.docx');h.core_properties.version='18';h.save(OUT/'Highlights_v18.docx')
    c=Document(OLD/'Cover_letter_MMT_v17.docx')
    for p in c.paragraphs:
        if p.text.startswith('The submission is accompanied'):
            p.text='The submission includes supplementary Tables S1–S32, Highlights and a version-18 reproducibility archive. Stress controls comprise 1100 selected synthetic fits, 3300 final attempts and 300 covariance-pilot attempts. They assess correlated noise, known and estimated covariance, periodic errors, gain and compliance mismatch. The deeper gain comparison uses 200 paired realizations with paired-bootstrap uncertainty; residual screening and noise-free transfer are reported alongside profile error. These controls do not replace measured-data validation or resolve omitted finite-element transition phases.'
    c.core_properties.version='18';c.save(OUT/'Cover_letter_MMT_v18.docx')
    (OUT/'editorial_changes_v18.json').write_text(json.dumps(dict(base='v17 clean',abstract_words=len(abst.split()),changed_paragraphs=changes,replaced_section='4.8',tables_added='S28–S32',original_tables_unchanged=True),ensure_ascii=False,indent=2),encoding='utf-8');print('Built four v18 documents; abstract words',len(abst.split()))
if __name__=='__main__':main()
